         /// <inheritdoc />
         [EditorBrowsable(EditorBrowsableState.Never)]
         public override int GetHashCode()
         {
             return HashCodeBuilder.Combine(Endpoint, Audience);
         }

         /// <inheritdoc />
         public override string ToString() => JsonSerializer.Serialize(this);
